// The current context's OpenGL functions (null without a current context).
static QOpenGLFunctions *qtf_gl() {
    QOpenGLContext *ctx = QOpenGLContext::currentContext();
    return ctx ? ctx->functions() : nullptr;
}

// The color of one pixel of the current framebuffer (x, y from the bottom left).
static QColor qtf_gl_read_pixel(int x, int y) {
    QOpenGLFunctions *f = qtf_gl();
    unsigned char p[4] = {0, 0, 0, 0};
    if (f) f->glReadPixels(x, y, 1, 1, GL_RGBA, GL_UNSIGNED_BYTE, p);
    return QColor(p[0], p[1], p[2], p[3]);
}

static QString qtf_gl_string(int name) {
    QOpenGLFunctions *f = qtf_gl();
    const GLubyte *s = f ? f->glGetString(GLenum(name)) : nullptr;
    return s ? QString::fromLatin1(reinterpret_cast<const char *>(s)) : QString();
}

// Fortran arrays are double / default integer; GL buffers hold float / uint.
static bool qtf_allocate_floats(QOpenGLBuffer *b, const double *data, int n) {
    std::vector<float> v(data, data + n);
    b->allocate(v.data(), int(v.size() * sizeof(float)));
    return true;
}

static bool qtf_allocate_uints(QOpenGLBuffer *b, const int *data, int n) {
    std::vector<GLuint> v(data, data + n);
    b->allocate(v.data(), int(v.size() * sizeof(GLuint)));
    return true;
}

// Matrices arrive column-major (Fortran m(4,4) / m(3,3)), as OpenGL expects.
static QMatrix4x4 qtf_mat4(const double *m) {
    QMatrix4x4 q;
    for (int c = 0; c < 4; ++c)
        for (int r = 0; r < 4; ++r) q(r, c) = float(m[c * 4 + r]);
    return q;
}

static QMatrix3x3 qtf_mat3(const double *m) {
    QMatrix3x3 q;
    for (int c = 0; c < 3; ++c)
        for (int r = 0; r < 3; ++r) q(r, c) = float(m[c * 3 + r]);
    return q;
}

// QtfOpenGLWidget: a QOpenGLWidget whose initializeGL / resizeGL / paintGL and
// input events are forwarded to Fortran slots (with the context current).

enum qtf_gl_event {
    QTF_GL_INITIALIZE,
    QTF_GL_RESIZE,
    QTF_GL_PAINT,
    QTF_GL_MOUSEPRESS,
    QTF_GL_MOUSERELEASE,
    QTF_GL_MOUSEMOVE,
    QTF_GL_MOUSEDOUBLECLICK,
    QTF_GL_WHEEL,
    QTF_GL_KEYPRESS,
    QTF_GL_KEYRELEASE,
    QTF_GL_COUNT
};

class QtfOpenGLWidget : public QOpenGLWidget {
  public:
    explicit QtfOpenGLWidget(QWidget *parent) : QOpenGLWidget(parent) { setFocusPolicy(Qt::StrongFocus); }

    // (not named `slots`: that is a Qt macro)
    std::array<std::vector<qtf_slot>, QTF_GL_COUNT> handlers;

  protected:
    // True if a (live) slot handled the event.
    bool forward(qtf_gl_event ev, void *p) {
        qtf_args a{};
        a.p = p;
        return qtf_emit_all(handlers[ev], a) > 0;
    }

    void initializeGL() override { forward(QTF_GL_INITIALIZE, nullptr); }
    void resizeGL(int, int) override { forward(QTF_GL_RESIZE, nullptr); }
    void paintGL() override { forward(QTF_GL_PAINT, nullptr); }
    void mousePressEvent(QMouseEvent *e) override {
        if (!forward(QTF_GL_MOUSEPRESS, e)) QOpenGLWidget::mousePressEvent(e);
    }
    void mouseReleaseEvent(QMouseEvent *e) override {
        if (!forward(QTF_GL_MOUSERELEASE, e)) QOpenGLWidget::mouseReleaseEvent(e);
    }
    void mouseMoveEvent(QMouseEvent *e) override {
        if (!forward(QTF_GL_MOUSEMOVE, e)) QOpenGLWidget::mouseMoveEvent(e);
    }
    void mouseDoubleClickEvent(QMouseEvent *e) override {
        if (!forward(QTF_GL_MOUSEDOUBLECLICK, e)) QOpenGLWidget::mouseDoubleClickEvent(e);
    }
    void wheelEvent(QWheelEvent *e) override {
        if (!forward(QTF_GL_WHEEL, e)) QOpenGLWidget::wheelEvent(e);
    }
    void keyPressEvent(QKeyEvent *e) override {
        if (!forward(QTF_GL_KEYPRESS, e)) QOpenGLWidget::keyPressEvent(e);
    }
    void keyReleaseEvent(QKeyEvent *e) override {
        if (!forward(QTF_GL_KEYRELEASE, e)) QOpenGLWidget::keyReleaseEvent(e);
    }
};

// Attach a slot to one of the QtfOpenGLWidget's handlers (owned by the widget).
template <qtf_gl_event EV> static bool connect_gl_event(void *s, const qtf_slot &ref) {
    auto *w = dynamic_cast<QtfOpenGLWidget *>(static_cast<QWidget *>(s));
    if (!w) return false;
    w->handlers[EV].push_back(ref);
    return true;
}

